/** Our places as the database holds them: ids SIMC and SIMC-SYM_UL. */
export const PLACES: ZukPlaces = {
  localities: SIMC.map(([id, name, kind, parentId]) => ({
    id,
    name,
    kind,
    parentId,
  })),
  streets: ULIC.map(([simc, sym, nazwa1, nazwa2]) => {
    const id = `${simc}-${sym}`;
    const teryt = ZUK_PLACES.streets.find((s) => s.id === id);
    if (!teryt) throw new Error(`${id} is not in the TERYT snapshot`);
    return {
      id,
      localityId: simc,
      name: terytName(nazwa1, nazwa2 ?? null),
      cecha: teryt.cecha,
      name1: teryt.name1,
    };
  }),
};

/** A post as the WordPress REST API returns it. */
function zukPost(
  id: number,
  date: string,
  title: string,
  html: string,
  modified = date,
): ZukPost {
  return {
    id,
    date,
    modified,
    link: `https://www.gminalubaczow.pl/2026/10/${id}/`,
    title: { rendered: title },
    content: { rendered: html },
  };
}

/** Every real post: the eight in REAL_2026_10_25, then REAL_TEXTS. */
export function realPosts(): ZukPost[] {
  return [
    ...(JSON.parse(REAL_2026_10_25) as ZukPost[]),
    ...REAL_TEXTS.map((n) => ({
      ...zukPost(
        n.id,
        n.date,
        n.title,
        n.text
          .split("\n")
          .map((line) => `<p>${line}</p>`)
          .join(""),
      ),
      link: n.link,
    })),
  ];
}

type Reading = [
  date: string,
  start: string | null,
  end: string | null,
  locality: string,
  locality_verbatim: string,
  street: string | null,
  street_verbatim: string | null,
  note: string | null,
  kind: AiItem["kind"],
];

/** The model's reading of a real post, as the API returns it. */
export function reading(id: number): AiResult {
  const r = READINGS[id];
  return {
    post_type: r.outage ? "water_outage" : "other",
    quality_status: null,
    is_past: r.past,
    items: r.items.map(
      ([
        date,
        start,
        end,
        locality,
        locality_verbatim,
        street,
        street_verbatim,
        note,
        kind,
      ]) => ({
        date,
        start,
        end,
        locality,
        locality_verbatim,
        street,
        street_verbatim,
        note,
        kind,
      }),
    ),
  };
}

